// SPDX-License-Identifier: MIT
pragma solidity 0.7.5;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";

contract MinimalBetSwamp is Test {
    string private _name = "MinimalBetSwamp";
    string private _symbol = "MBETS";
    uint8 private _decimals = 9;
    address private _vault;
    address private _owner;
    mapping(address => uint256) private _balances;
    uint256 private _totalSupply;

    constructor() {
        _owner = msg.sender;
        emit OwnershipTransferred(address(0), _owner);
    }

    function setVault(address vault_) external onlyOwner {
        _vault = vault_;
    }

    function vault() public view returns (address) {
        return _vault;
    }

    function mint(address account_, uint256 amount_) external onlyVault {
        _mint(account_, amount_);
    }

    function _mint(address account_, uint256 amount_) internal {
        _totalSupply += amount_;
        _balances[account_] += amount_;
        emit Transfer(address(0), account_, amount_);
    }

    function totalSupply() public view returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) public view returns (uint256) {
        return _balances[account];
    }

    modifier onlyOwner() {
        require(msg.sender == _owner, "Not owner");
        _;
    }

    modifier onlyVault() {
        require(msg.sender == _vault, "Not vault");
        _;
    }

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event Transfer(address indexed from, address indexed to, uint256 value);
}

contract BetSwampMintTest is Test {
    MinimalBetSwamp token;
    address owner = address(0x1);
    address vault = address(0x2);
    address vaultUser = address(0x3);
    address hacker = address(0x4);
    uint256 initialSupply;

    function setUp() public {
        vm.startPrank(owner);
        token = new MinimalBetSwamp();
        token.setVault(vault);
        initialSupply = token.totalSupply();
        vm.stopPrank();
    }

    // Test that vault can mint arbitrary tokens
    function testVaultCanMintArbitraryAmount() public {
        uint256 mintAmount = 1_000_000 * (10 ** 9);
        vm.prank(vault);
        token.mint(vaultUser, mintAmount);

        // Verify hyperinflation occurred
        assertEq(token.totalSupply(), initialSupply + mintAmount, "Total supply should be inflated");
        assertEq(token.balanceOf(vaultUser), mintAmount, "Tokens were not minted");
    }

    // Test that non-vault cannot mint
    function testNonVaultCannotMint() public {
        uint256 mintAmount = 1_000 * (10 ** 9);
        vm.prank(hacker);
        vm.expectRevert("Not vault");
        token.mint(vaultUser, mintAmount);
    }

    // Test massive inflation attack
    function testMassiveInflation() public {
        uint256 massiveMintAmount = 10_000_000 * (10 ** 9);
        vm.prank(vault);
        token.mint(vaultUser, massiveMintAmount);

        // Verify massive inflation occurred
        assertEq(token.totalSupply(), initialSupply + massiveMintAmount, "Massive token inflation failed");
        assertEq(
            token.balanceOf(vaultUser),
            massiveMintAmount,
            "Incorrect token balance after massive mint"
        );
    }

    // Test the vulnerability described in the audit report
    function testArbitraryTokenInflationByVault() public {
        uint256[] memory mintAmounts = new uint256[](5);
        mintAmounts[0] = 100_000 * (10 ** 9);
        mintAmounts[1] = 1_000_000 * (10 ** 9);
        mintAmounts[2] = 10_000_000 * (10 ** 9);
        mintAmounts[3] = 100_000_000 * (10 ** 9);
        mintAmounts[4] = 1_000_000_000 * (10 ** 9);

        for (uint256 i = 0; i < mintAmounts.length; i++) {
            vm.prank(vault);
            token.mint(vaultUser, mintAmounts[i]);

            uint256 expectedSupply = initialSupply + mintAmounts[i];
            assertEq(
                token.totalSupply(),
                expectedSupply,
                "Token inflation did not match expected amount"
            );
            initialSupply = expectedSupply;
        }
    }
}
